import{$,$$,emit,t,prefersReducedMotion,clamp,announce}from"./utils.js";let container;let screens=[];let activeIndex=0;let locked=false;let observer=null;let rebuilding=false;export function getActiveIndex(){if(container?.clientHeight){return clamp(Math.round(container.scrollTop/container.clientHeight),0,Math.max(screens.length-1,0));}
return activeIndex;}
export function getScreens(){return screens;}
export function init(){container=$("#snap");bindScreens();initWheelAndKeys();initTouchYield();initHash();initGotoButtons();}
function initTouchYield(){const yield_=()=>cancelPageTween();container.addEventListener("touchstart",yield_,{passive:true});container.addEventListener("pointerdown",(e)=>{if(e.pointerType!=="mouse")yield_();},{passive:true});}
export function rebind(keepIndex=0){rebuilding=true;bindScreens();goTo(keepIndex,true);requestAnimationFrame(()=>{rebuilding=false;});}
function bindScreens(){screens=$$(".screen",container);buildRail();observeActive();}
let io=null;function observeActive(){io?.disconnect();io=new IntersectionObserver((entries)=>{let best=null;for(const entry of entries){if(!entry.isIntersecting)continue;if(!best||entry.intersectionRatio>best.intersectionRatio)best=entry;}
if(!best)return;const index=screens.indexOf(best.target);if(index===-1||(index===activeIndex&&!rebuilding))return;setActive(index);},{root:container,threshold:0.6},);screens.forEach((s)=>io.observe(s));}
let settleTimer=null;function setActive(index){activeIndex=index;const section=screens[index];updateRail(index);updateCatBar(section,index);updateHash(section);clearTimeout(settleTimer);settleTimer=setTimeout(()=>{const landed=getActiveIndex();const target=screens[landed]||section;announceScreen(target,landed);emit("dish:active",{index:landed,section:target,dishId:target.classList.contains("dish")?target.id:null,mood:target.dataset.mood||"paper",});},140);}
function announceScreen(section,index){if(section.classList.contains("dish")){const dishes=screens.filter((s)=>s.classList.contains("dish"));const i=dishes.indexOf(section)+1;announce(`${t("dishOf", { i, n: dishes.length })} — ${section.getAttribute("aria-label")}`);}else{announce(section.getAttribute("aria-label")||"");}}
let pageTween=null;let cooldown=null;function settleTween(){container.classList.remove("is-tweening");clearTimeout(cooldown);cooldown=setTimeout(()=>{locked=false;},180);}
export function cancelPageTween(){if(!pageTween)return;pageTween.kill();pageTween=null;container.classList.remove("is-tweening");clearTimeout(cooldown);locked=false;}
const canHover=()=>window.matchMedia("(hover: hover) and (pointer: fine)").matches;export function goTo(index,instant=false){index=clamp(index,0,screens.length-1);const top=screens[index]?.offsetTop??index*container.clientHeight;if(instant||prefersReducedMotion()||!window.gsap||document.visibilityState==="hidden"){cancelPageTween();container.scrollTo({top,behavior:"auto"});return;}
if(!canHover()){cancelPageTween();locked=true;container.scrollTo({top,behavior:"smooth"});clearTimeout(cooldown);cooldown=setTimeout(()=>{locked=false;},420);return;}
pageTween?.kill();locked=true;container.classList.add("is-tweening");const proxy={v:container.scrollTop};pageTween=gsap.to(proxy,{v:top,duration:0.62,ease:"power2.inOut",onUpdate:()=>{container.scrollTop=proxy.v;},onComplete:settleTween,onInterrupt:settleTween,});}
function initWheelAndKeys(){if(!prefersReducedMotion()&&window.Observer){gsap.registerPlugin(Observer);observer=Observer.create({target:container,type:"wheel",preventDefault:true,tolerance:8,onDown:()=>step(1),onUp:()=>step(-1),});}
document.addEventListener("keydown",(e)=>{if(e.defaultPrevented)return;const sheet=$("#order-sheet");if(sheet?.open)return;const el=document.activeElement;const tag=el?.tagName;if(tag==="INPUT"||tag==="TEXTAREA"||el?.isContentEditable)return;const focusIsInteractive=tag==="BUTTON"||tag==="A"||tag==="SELECT"||tag==="SUMMARY";switch(e.key){case"ArrowDown":case"PageDown":e.preventDefault();step(1);break;case" ":if(focusIsInteractive)return;e.preventDefault();step(e.shiftKey?-1:1);break;case"ArrowUp":case"PageUp":e.preventDefault();step(-1);break;case"Home":e.preventDefault();goTo(0);break;case"End":e.preventDefault();goTo(screens.length-1);break;}});}
function step(dir){if(locked)return;const current=Math.round(container.scrollTop/container.clientHeight);goTo(current+dir);}
let railGroups=[];function buildRail(){const rail=$("#rail");rail.setAttribute("aria-label",t("railAria"));rail.innerHTML="";railGroups=[];let current=null;screens.forEach((s,i)=>{const key=s.dataset.rail||s.id||`screen-${i}`;if(!current||current.key!==key){current={key,first:i,last:i,label:s.getAttribute("aria-label")||`Screen ${i + 1}`,};railGroups.push(current);}else{current.last=i;}});railGroups.forEach((g)=>{const b=document.createElement("button");b.type="button";b.setAttribute("aria-label",g.label);b.addEventListener("click",()=>goTo(g.first));rail.append(b);});updateRail(activeIndex);}
function updateRail(index){const btns=$$("#rail button");railGroups.forEach((g,gi)=>{if(index>=g.first&&index<=g.last)btns[gi]?.setAttribute("aria-current","true");else btns[gi]?.removeAttribute("aria-current");});}
let chipTimer=null;function updateCatBar(section,index){const bar=$("#catbar");const group=section.dataset.rail||"";const away=index!==0;$("#sections-fab")?.setAttribute("data-visible",String(away));$$("#sections-list [data-rail]").forEach((row)=>{row.setAttribute("aria-current",String(row.dataset.rail===group));});if(!bar)return;bar.dataset.visible=String(away);let active=null;$$(".catbar__chip",bar).forEach((chip)=>{const on=chip.dataset.rail===group;chip.setAttribute("aria-current",String(on));if(on)active=chip;});if(!active)return;clearTimeout(chipTimer);chipTimer=setTimeout(()=>{const target=active.offsetLeft-(bar.clientWidth-active.offsetWidth)/2;bar.scrollTo({left:target,behavior:"auto"});},160);}
let hashTimer;function updateHash(section){clearTimeout(hashTimer);hashTimer=setTimeout(()=>{const id=section.id||"";if(id&&id!=="top")history.replaceState(null,"",`#${id}`);else history.replaceState(null,"",location.pathname+location.search);},300);}
function initHash(){const id=location.hash.slice(1);if(!id)return;const target=screens.findIndex((s)=>s.id===id);if(target>0)goTo(target,true);}
function initGotoButtons(){document.addEventListener("click",(e)=>{const el=e.target.closest("[data-goto]");if(!el)return;e.preventDefault();if(locked)return;const v=el.dataset.goto;const n=Number(v);const index=Number.isNaN(n)?screens.findIndex((s)=>s.id===v):n;if(index>=0)goTo(index);});}
export function initNavAutoHide(){$("#nav").dataset.hidden="false";}